<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class H5PAddQuestionSetOneTwentyOneSeeder extends Seeder
{
    public function run()
    {
        $h5pQuestionSetLibParams = ['name' => "H5P.QuestionSet", "major_version" => 1, "minor_version" => 21];
        $h5pQuestionSetLib = DB::table('h5p_libraries')->where($h5pQuestionSetLibParams)->first();

        if (empty($h5pQuestionSetLib)) {
            $h5pQuestionSetLibId = DB::table('h5p_libraries')->insertGetId([
                'name' => 'H5P.QuestionSet',
                'title' => 'Question Set',
                'major_version' => 1,
                'minor_version' => 21,
                'patch_version' => 13,
                'embed_types' => 'iframe',
                'runnable' => 1,
                'restricted' => 0,
                'fullscreen' => 0,
                'preloaded_js' => 'js/questionset.js',
                'preloaded_css' => 'css/questionset.css',
                'drop_library_css' => '',
                'semantics' => $this->getSemantics(),
                'tutorial_url' => ' ',
                'has_icon' => 1
            ]);

            $this->insertDependentLibraries($h5pQuestionSetLibId);
            $this->insertLibrariesLanguages($h5pQuestionSetLibId);

            $currentDate = now();
            $organizations = DB::table('organizations')->pluck('id');

            foreach ($organizations as $organizationId) {
                $activityTypes = DB::table('activity_types')->whereOrganizationId($organizationId)->pluck('id', 'title');
                if (!isset($activityTypes['Multimedia'])) {
                    continue;
                }
                $params = ['title' => 'Quiz (Question Set)', 'organization_id' => $organizationId];
                DB::table('activity_items')->updateOrInsert($params, [
                    'title' => 'Quiz (Question Set)',
                    'image' => '',
                    'description' => 'Create a quiz with multiple question types',
                    'activity_type_id' => $activityTypes['Multimedia'],
                    'h5pLib' => 'H5P.QuestionSet 1.21',
                    'demo_activity_id' => '0',
                    'demo_video_id' => '',
                    'type' => 'h5p',
                    'created_at' => $currentDate,
                    'deleted_at' => null,
                    'organization_id' => $organizationId,
                ]);
            }
        }
    }

    private function insertDependentLibraries($h5pQuestionSetLibId)
    {
        // Preloaded Dependencies
        $h5pFontAwesomeParams = ['name' => "FontAwesome", "major_version" => 4, "minor_version" => 5];
        $h5pFontAwesomeLib = DB::table('h5p_libraries')->where($h5pFontAwesomeParams)->first();
        $h5pFontAwesomeLibId = $h5pFontAwesomeLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pFontAwesomeLibId,
            'dependency_type' => 'preloaded'
        ]);

        $h5pVideoParams = ['name' => "H5P.Video", "major_version" => 1, "minor_version" => 6];
        $h5pVideoLib = DB::table('h5p_libraries')->where($h5pVideoParams)->first();
        $h5pVideoLibId = $h5pVideoLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pVideoLibId,
            'dependency_type' => 'preloaded'
        ]);

        $h5pJoubelUIParams = ['name' => "H5P.JoubelUI", "major_version" => 1, "minor_version" => 3];
        $h5pJoubelUILib = DB::table('h5p_libraries')->where($h5pJoubelUIParams)->first();
        $h5pJoubelUILibId = $h5pJoubelUILib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pJoubelUILibId,
            'dependency_type' => 'preloaded'
        ]);

        $h5pComponentsParams = ['name' => "H5P.Components", "major_version" => 1, "minor_version" => 0];
        $h5pComponentsLib = DB::table('h5p_libraries')->where($h5pComponentsParams)->first();
        $h5pComponentsLibId = $h5pComponentsLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pComponentsLibId,
            'dependency_type' => 'preloaded'
        ]);

        // Editor Dependencies
        $h5pRangeListParams = ['name' => "H5PEditor.RangeList", "major_version" => 1, "minor_version" => 0];
        $h5pRangeListLib = DB::table('h5p_libraries')->where($h5pRangeListParams)->first();
        $h5pRangeListLibId = $h5pRangeListLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pRangeListLibId,
            'dependency_type' => 'editor'
        ]);

        $h5pVerticalTabsParams = ['name' => "H5PEditor.VerticalTabs", "major_version" => 1, "minor_version" => 3];
        $h5pVerticalTabsLib = DB::table('h5p_libraries')->where($h5pVerticalTabsParams)->first();
        $h5pVerticalTabsLibId = $h5pVerticalTabsLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pVerticalTabsLibId,
            'dependency_type' => 'editor'
        ]);

        $h5pQSTextualEditorParams = ['name' => "H5PEditor.QuestionSetTextualEditor", "major_version" => 1, "minor_version" => 3];
        $h5pQSTextualEditorLib = DB::table('h5p_libraries')->where($h5pQSTextualEditorParams)->first();
        $h5pQSTextualEditorLibId = $h5pQSTextualEditorLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pQSTextualEditorLibId,
            'dependency_type' => 'editor'
        ]);

        $h5pShowWhenParams = ['name' => "H5PEditor.ShowWhen", "major_version" => 1, "minor_version" => 0];
        $h5pShowWhenLib = DB::table('h5p_libraries')->where($h5pShowWhenParams)->first();
        $h5pShowWhenLibId = $h5pShowWhenLib->id;
        DB::table('h5p_libraries_libraries')->insert([
            'library_id' => $h5pQuestionSetLibId,
            'required_library_id' => $h5pShowWhenLibId,
            'dependency_type' => 'editor'
        ]);
    }

